int minPathSum(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (r == 0 && c == 0) continue;
            int top = r > 0 ? grid[r - 1][c] : Integer.MAX_VALUE;
            int left = c > 0 ? grid[r][c - 1] : Integer.MAX_VALUE;
            grid[r][c] += Math.min(top, left);
        }
    }
    return grid[m - 1][n - 1];
}

